---
import BookmarkIcon from "@lucide/astro/icons/bookmark"

import { Toggle } from "@/components/ui/toggle"

const translations = {
  en: {
    dir: "ltr",
    values: {
      label: "Bookmark",
    },
  },
  ar: {
    dir: "rtl",
    values: {
      label: "إشارة مرجعية",
    },
  },
  he: {
    dir: "rtl",
    values: {
      label: "סימנייה",
    },
  },
} as const

const { dir, values: t } = translations.ar
---

<Toggle aria-label="Toggle bookmark" size="sm" variant="outline" dir={dir}>
  <BookmarkIcon class="group-aria-pressed/toggle:fill-foreground" />
  {t.label}
</Toggle>
